CREATE TYPE "ProductFactSource" AS ENUM ('USER_VERIFIED', 'AUTHORIZED_SOURCE');
CREATE TYPE "ListingDraftStatus" AS ENUM ('DRAFT', 'APPROVED');
CREATE TYPE "ListingClaimStatus" AS ENUM ('VERIFIED', 'UNVERIFIED');
CREATE TABLE "product_facts" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "project_id" TEXT NOT NULL, "fact_key" TEXT NOT NULL, "value" TEXT NOT NULL, "source" "ProductFactSource" NOT NULL, "evidence_reference" TEXT NOT NULL, "verified_at" TIMESTAMP(3) NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "product_facts_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "product_facts_unique" ON "product_facts"("organization_id", "project_id", "fact_key", "value"); CREATE INDEX "product_facts_project" ON "product_facts"("organization_id", "project_id", "verified_at");
ALTER TABLE "product_facts" ADD CONSTRAINT "product_facts_org" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "product_facts" ADD CONSTRAINT "product_facts_project" FOREIGN KEY ("project_id", "organization_id") REFERENCES "research_projects"("id", "organization_id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "listing_drafts" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "project_id" TEXT NOT NULL, "marketplace_id" TEXT NOT NULL, "version" INTEGER NOT NULL, "status" "ListingDraftStatus" NOT NULL DEFAULT 'DRAFT', "content" JSONB NOT NULL, "keyword_refs" JSONB NOT NULL, "warnings" JSONB NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "listing_drafts_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "listing_drafts_version" ON "listing_drafts"("organization_id", "project_id", "version"); CREATE INDEX "listing_drafts_project" ON "listing_drafts"("organization_id", "project_id", "updated_at");
ALTER TABLE "listing_drafts" ADD CONSTRAINT "listing_drafts_org" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "listing_drafts" ADD CONSTRAINT "listing_drafts_project" FOREIGN KEY ("project_id", "organization_id") REFERENCES "research_projects"("id", "organization_id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "listing_draft_claims" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "draft_id" TEXT NOT NULL, "section" TEXT NOT NULL, "phrase" TEXT NOT NULL, "status" "ListingClaimStatus" NOT NULL, "product_fact_id" TEXT, "keyword_refs" JSONB NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "listing_draft_claims_pkey" PRIMARY KEY ("id"));
CREATE INDEX "listing_draft_claims_status" ON "listing_draft_claims"("organization_id", "draft_id", "status");
ALTER TABLE "listing_draft_claims" ADD CONSTRAINT "listing_draft_claims_org" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "listing_draft_claims" ADD CONSTRAINT "listing_draft_claims_draft" FOREIGN KEY ("draft_id") REFERENCES "listing_drafts"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "listing_draft_claims" ADD CONSTRAINT "listing_draft_claims_fact" FOREIGN KEY ("product_fact_id") REFERENCES "product_facts"("id") ON DELETE SET NULL ON UPDATE CASCADE;
